/*
 * build/common.js — shared helpers of the build modules (tools/build.js).
 *
 * Every generated file starts with the GENERATED header (spec 02 §4) and assigns into window.LM,
 * so it loads with a plain <script> tag (works from file://, no fetch()).
 */
"use strict";

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..", "..");
const CONTENT = path.join(ROOT, "content");
const DATA = path.join(ROOT, "data");
const LEVELS = ["A1", "A2", "B1", "B2", "C1", "C2"];

function read(file) { return fs.readFileSync(file, "utf8").replace(/^﻿/, "").replace(/\r\n/g, "\n"); }
function readJson(file) { return JSON.parse(read(file)); }
function exists(file) { return fs.existsSync(file); }
function content(...parts) { return path.join(CONTENT, ...parts); }

/** Files of one folder (sorted), filtered by a RegExp on the name; [] when the folder is missing. */
function list(dir, re) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).filter(function (f) { return re.test(f) && fs.statSync(path.join(dir, f)).isFile(); }).sort();
}

/** Front matter (key: value) and the body without it. */
function splitMd(md) {
  const m = /^---\n([\s\S]*?)\n---\n?/.exec(md);
  const meta = {};
  if (m) m[1].split("\n").forEach(function (line) { const k = /^(\w+):\s*(.*)$/.exec(line); if (k) meta[k[1]] = k[2].trim(); });
  return { meta: meta, body: m ? md.slice(m[0].length) : md };
}

const written = [];

/**
 * Writes data/<rel> with the GENERATED header.
 *   rel      path under data/ ("pages.js", "sets/a1-x-1.js")
 *   sources  what it was made from, relative to the repo ("content/pages/…")
 *   body     JavaScript after the "window.LM = window.LM || {};" line
 */
function writeData(rel, sources, body) {
  const file = path.join(DATA, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const src = [].concat(sources).join(", ");
  fs.writeFileSync(file, "/* GENERATED by tools/build.js — do not edit. Source: " + src + " */\n" +
    "window.LM = window.LM || {};\n" + body.replace(/\s+$/, "") + "\n", "utf8");
  written.push(rel.replace(/\\/g, "/"));
  return "data/" + rel.replace(/\\/g, "/");
}

/** Topic id ("a1-cases-accusative") → page file under content/pages ("a1/cases-accusative.md"). */
function pageFileOf(topicId) {
  const m = /^([abc][12])-(.+)$/.exec(topicId);
  return m ? m[1] + "/" + m[2] + ".md" : null;
}

/** All syllabus topics in order: [{ id, level, unit, category, title, example }]. */
function topicsOf(syllabus) {
  const out = [];
  syllabus.levels.forEach(function (l) {
    l.units.forEach(function (u) {
      u.topics.forEach(function (t) { out.push(Object.assign({ level: l.id, unit: u.id }, t)); });
    });
  });
  return out;
}

const warnings = [];
function warn(msg) { warnings.push(msg); }

module.exports = {
  ROOT, CONTENT, DATA, LEVELS, read, readJson, exists, content, list, splitMd,
  writeData, written, pageFileOf, topicsOf, warn, warnings
};
